builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.Authority = "https://login.microsoftonline.com/{tenantId}/v2.0";
        options.Audience = "api://orders-api-client-id";
        options.TokenValidationParameters.ValidateAudience = true;
    });

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("OrdersRead", p => p.RequireClaim("scp", "Orders.Read"));
    // Entra v2 access tokens often use 'scp' for delegated scopes
});

// Worker service obtains token — no user context
var tokenResponse = await http.PostAsync("https://login.example.com/connect/token",
    new FormUrlEncodedContent(new Dictionary<string, string>
    {
        ["grant_type"] = "client_credentials",
        ["client_id"] = clientId,
        ["client_secret"] = clientSecret,
        ["scope"] = "orders.read orders.write"
    }));

// Call API
http.DefaultRequestHeaders.Authorization =
    new AuthenticationHeaderValue("Bearer", accessToken);

// API policy: RequireClaim("scope", "orders.write") for machine clients

builder.Services.AddAuthentication(options =>
{
    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = OpenIdConnectDefaults.AuthenticationScheme;
})
.AddCookie()
.AddOpenIdConnect(options =>
{
    options.Authority = "https://login.example.com";
    options.ClientId = "bff-client";
    options.ResponseType = OpenIdConnectResponseType.Code;
    options.UsePkce = true;
    options.SaveTokens = true; // access token in auth session
});

// BFF forwards access token to downstream API — SPA never holds refresh token

options.Events = new JwtBearerEvents
{
    OnAuthenticationFailed = ctx =>
    {
        if (ctx.Exception is SecurityTokenSignatureKeyNotFoundException)
        {
            // Signing keys rotated — metadata cache stale
            var configManager = (ctx.Options.ConfigurationManager as
                BaseConfigurationManager);
            configManager?.RequestRefresh();
        }
        return Task.CompletedTask;
    }
};
